// --- the Python source of truth ------------------------------------------------------

/** Extract a `NAME = """..."""` .split() block from the Python module, verbatim. */
function pythonWordList(source: string, name: string): string[] {
  const m = new RegExp(`^${name} = """([\\s\\S]*?)"""\\.split\\(\\)`, "m").exec(source);
  if (!m) throw new Error(`could not find the Python list ${name} — has lex/dolch.py been restructured?`);
  return m[1].split(/\s+/).filter((w) => w.length > 0);
}

const pySource = fs.readFileSync(PY_DOLCH, "utf-8");

/** The Gutenberg body, trimmed the way `lex/corpus.py` trims it before use. */
function corpusBody(raw: string): string {
  const lines = raw.split(/\r?\n/);
  let start = 0;
  let end = lines.length;
  for (let i = 0; i < lines.length; i++) {
    if (lines[i].includes("*** START OF THE PROJECT GUTENBERG")) start = i + 1;
    else if (lines[i].includes("*** END OF THE PROJECT GUTENBERG")) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join("\n").replace(/^\n+|\n+$/g, "");
}

const corpusText = corpusBody(fs.readFileSync(CORPUS, "utf-8"));

// --- Dolch ---------------------------------------------------------------------------

describe("Dolch lists", () => {
  it("transcribes lex/dolch.py word for word", () => {
    const pairs: [string, string[]][] = [
      ["PRE_PRIMER", PRE_PRIMER],
      ["PRIMER", PRIMER],
      ["FIRST", FIRST],
      ["SECOND", SECOND],
      ["THIRD", THIRD],
      ["NOUNS", NOUNS],
    ];
    for (const [name, ts] of pairs) {
      expect(ts, `${name} differs from Python`).toEqual(pythonWordList(pySource, name));
    }
  });

  it("keeps both corrections: first grade has `going`, not `giving`", () => {
    expect(FIRST).toContain("going");
    expect(FIRST).not.toContain("giving");
    // `give` is separately present, which is why `giving` was a slip and not a variant.
    expect(FIRST).toContain("give");
    for (const name of DOLCH_ORDER) expect(dolchBudget(name)).not.toContain("giving");
  });

  it("drops `Santa Claus`: no budget entry contains a space", () => {
    for (const name of DOLCH_ORDER) {
      for (const w of dolchBudget(name)) expect(w).not.toMatch(/\s/);
    }
    expect(NOUNS).not.toContain("Santa");
    expect(NOUNS).not.toContain("Claus");
    expect(dolchBudget("full")).not.toContain("santa claus");
  });

  it("measures the budget sizes 40/92/133/220/314", () => {
    expect(dolchSizes()).toEqual({ pre_primer: 40, primer: 92, first: 133, service: 220, full: 314 });
  });

  it("nests each budget in the next", () => {
    for (let i = 1; i < DOLCH_ORDER.length; i++) {
      const smaller = dolchBudget(DOLCH_ORDER[i - 1]);
      const larger = new Set(dolchBudget(DOLCH_ORDER[i]));
      for (const w of smaller) expect(larger.has(w)).toBe(true);
    }
  });
});

